parameters.functionScript:
function wordMap(rows, lang, name) {
  var map = {};
  var list = Array.isArray(rows) ? rows : [];
  for (var i = 0; i < list.length; i++) if (list[i] && list[i].key) map[list[i].key] = String(list[i][lang] || list[i].en || '').split('{b}').join(name);
  return map;
}
function fill(text, vars) { var t = String(text || ''); for (var k in vars) t = t.split('{' + k + '}').join(String(vars[k])); return t; }
function langOf(v) { return String(v) === 'fr' ? 'fr' : 'en'; }
function nameOf(v) { var n = String(v || '').trim(); return n || 'Pip'; }

var PAD = [["fwd","bg-key-fwd","fwd","bFwd"],["left","bg-key-left","left","bLeft"],["water","","water","bWater"],["right","bg-key-right","right","bRight"],["fill","","fill","bFill"],["pick","","pick","bPick"],["put","","put","bPut"],["say","","say","bSay"],["olive:read","","read","rungRead"]];
// IG-003: the key's label (what a screen reader says; the key shows its icon) is the step's word in the child's language —
// the pad is up from the moment a request opens (Drive), and an English op name there was the one word a switch left.
var W = wordMap(Inputs.words, langOf(Inputs.lang), 'Pip');
var KNOWN = ["fwd","left","right","water","fill","pick","put","say","repeat","until","if","when","count_inc","trick","do","ask","go_nearest","go_to","set","change"];
// P108 IW-001 F7: the pad is the DRAWER's actions — the palette the kit shows (band x request x robot, Olive's rungs
// included), so "read" is a key where the drawer has it; with no palette, the request's allowed list as before.
var pal = Array.isArray(Inputs.palette) ? Inputs.palette : [];
var drawer = [];
for (var p = 0; p < pal.length; p++) if (pal[p] && pal[p].id) drawer.push(String(pal[p].id));
var allowed = drawer.length ? drawer : Array.isArray(Inputs.allowed) ? Inputs.allowed : [];
var slots = ['bg-key-mid', 'bg-key-r3a', 'bg-key-r3b', 'bg-key-r3c', 'bg-key-r4a', 'bg-key-r4b', 'bg-key-r4c'], used = 0;
var keys = [];
for (var i = 0; i < PAD.length; i++) {
  var op = PAD[i][0];
  var ok = allowed.length ? allowed.indexOf(op) !== -1 : KNOWN.indexOf(op) !== -1;
  if (!ok) continue;
  var place = PAD[i][1] || slots[Math.min(used++, slots.length - 1)];
  var slug = op.replace(/[^a-z0-9]+/gi, '-');
  // 🔴 A stable row id per key (a row is a Noodl Object, global by id): the keys arrive twice as a request opens (its
  // allowed list, then the drawer's palette), and two lists of id-less rows in quick succession left the For Each
  // with BOTH sets (the page drive: ten keys on the tulips, each under its twin, so no press landed).
  keys.push({ id: 'padkey-' + slug, op: op, cls: 'bg-key bg-key-' + slug + (place === 'bg-key-' + slug ? '' : ' ' + place) + ' bg-i-' + PAD[i][2] + ' bg-press', label: W[PAD[i][3]] || op });
}
Outputs.keys = keys;
Outputs.count = keys.length;
